    "id": 17,
    "title": "Hướng dẫn quy chuẩn phân loại rác thải 8 loại nghiêm ngặt tại các đô thị Nhật Bản",
    "slug": "huong-dan-quy-chuan-phan-loai-rac-thai-8-loai-nghiem-ngat-tai-cac-do-thi-nhat-ban",
    "category": "Văn hóa Nhật",
    "summary": "Những nguyên tắc sống còn về việc phân loại rác cháy được, rác không cháy, chai nhựa PET và ngày vứt rác tại các khu dân cư Nhật Bản để tránh bị phạt.",
    "content": "Một trong những cú sốc văn hóa đầu tiên mà bất kỳ du học sinh hay thực tập sinh nào cũng gặp phải khi mới đặt chân sang Nhật là quy định phân loại và xử lý rác thải sinh hoạt cực kỳ nghiêm ngặt.\n\nQuy tắc phân loại cơ bản:\n1. Rác cháy được (Moeru Gomi): Thức ăn thừa, giấy vụn, lá cây, quần áo cũ, đồ gỗ nhỏ. Rác này thường được thu gom 2 đến 3 lần mỗi tuần trong túi rác màu vàng hoặc hồng theo quy định riêng của từng quận (City Hall).\n2. Rác không cháy được (Moenai Gomi): Đồ thủy tinh vỡ, gốm sứ, kim loại nhỏ, bóng đèn, pin cũ. Phải được bọc cẩn thận và để vào túi quy định.\n3. Chai nhựa PET và lon nhôm: Phải bóc sạch màng nhãn nilon, tháo nắp chai riêng, tráng sạch nước bên trong chai, đạp dẹp rồi mới bỏ vào thùng gom chuyên dụng.\n4. Rác cồng kềnh (Sodai Gomi): Bàn ghế, đệm, xe đạp, vali lớn... Tuyệt đối không được tự ý vứt ra bãi rác. Bạn phải mua tem rác cồng kềnh tại cửa hàng tiện lợi Konbini và gọi điện đặt lịch hẹn với trung tâm xử lý rác của phường đến thu gom.\n\nTại Nhật Bản, hành vi vứt rác sai ngày hoặc vứt rác trộm có thể bị ban quản lý tòa nhà nhắc nhở phạt tiền hoặc thậm chí bị hàng xóm báo cảnh sát xử phạt hành chính theo luật Bảo vệ Môi trường.",
    "imageUrl": "https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=80",
    "imageAlt": "Hướng dẫn quy chuẩn phân loại rác thải 8 loại nghiêm ngặt tại các đô thị Nhật Bản",
